from collections import Counter, defaultdict

def basicCalculatorIV(expression, evalvars, evalints):
    # Map provided variables to their values
    val_dict = dict(zip(evalvars, evalints))

    # Tokenizer to split tokens
    def tokenize(expr):
        tokens = []
        i, n = 0, len(expr)
        while i < n:
            if expr[i] == ' ':
                i += 1
            elif expr[i] in "+-*()":
                tokens.append(expr[i])
                i += 1
            else:
                j = i
                while j < n and expr[j] not in " +-*()":
                    j += 1
                tokens.append(expr[i:j])
                i = j
        return tokens

    # Helper to add or combine two terms (Counters)
    def combine(a, b, sign=1):
        for k, v in b.items():
            a[k] += sign * v
        return a

    # Multiply two terms
    def multiply(a, b):
        res = Counter()
        for k1, v1 in a.items():
            for k2, v2 in b.items():
                # merge variable parts
                if k1 == '':
                    vpart = k2
                elif k2 == '':
                    vpart = k1
                else:
                    vpart = '*'.join(sorted(k1.split('*') + k2.split('*')))
                res[vpart] += v1 * v2
        return res

    # Parse expression with recursive descent
    def parse(tokens):
        def parseTerm():
            token = tokens.pop(0)
            if token == '(':
                res = parseExpr()
                tokens.pop(0) # pop ')'
                return res
            elif token.isdigit():
                return Counter({'': int(token)})
            elif token.isalpha():
                if token in val_dict:
                    return Counter({'': val_dict[token]})
                return Counter({token: 1})
            return Counter()

        def parseFactor():
            stack = [parseTerm()]
            while tokens and tokens[0] == '*':
                tokens.pop(0)
                stack.append(parseTerm())
            res = stack[0]
            for i in range(1, len(stack)):
                res = multiply(res, stack[i])
            return res

        def parseExpr():
            res = parseFactor()
            while tokens and (tokens[0] == '+' or tokens[0] == '-'):
                op = tokens.pop(0)
                fac = parseFactor()
                if op == '+':
                    res = combine(res, fac)
                else:
                    res = combine(res, fac, -1)
            return res
        return parseExpr()

    # Main logic
    tokens = tokenize(expression)
    count = parse(tokens)

    # Remove zero-coefficient terms
    count = {k: v for k, v in count.items() if v != 0}

    # Collect and sort by degree desc and lex
    def sort_key(item):
        k, v = item
        vars_split = k.split('*') if k else []
        return (-len(vars_split), vars_split)
    items = sorted(count.items(), key=sort_key)

    # Format output
    res = []
    for vars_part, coeff in items:
        if coeff == 0:
            continue
        s = str(coeff)
        if vars_part:
            s += '*' + vars_part
        res.append(s)
    return res
